  assert.deepEqual(rule.run(ctxWith({ workflow: FILTERED })), []);
});

test('stays quiet when the doc makes no path claim about an unfiltered workflow', () => {
  assert.deepEqual(rule.run(ctxWith({ doc: CLAIMS_NOTHING })), []);
